def main() -> None:
    p = argparse.ArgumentParser()
    p.add_argument("hashes", nargs="*", help="hash12 list; default = pending develop")
    p.add_argument("--max-turns", type=int, default=3)
    args = p.parse_args()
    want = args.hashes or develop_hashes()
    for h in want:
        if already_done(REPLAY / h):
            print(f"{h} skip")
            continue
        try:
            status = run_hash(h, args.max_turns)
        except subprocess.TimeoutExpired:
            status = "timeout"
            (REPLAY / h / "opencode.err").write_text("timeout\n", encoding="utf-8")
        print(f"{h} {status}")


if __name__ == "__main__":
    main()
